#include "stdafx.h"#include "ModbusTcpServerImpl.h"LRESULT KModbusTcpServerImpl::NetworkWndProcImpl( HWND hWnd, UINT msg, WPARAM wParam, LPARAM lParam ){  switch( msg )  {  case WM_CREATE:    m_hNetworkCmdWnd = hWnd;    {      WSADATA wsaData;      if( WSAStartup(WINSOCK_VERSION, &wsaData) )      {        MessageBox( NULL, "Ошибка на WSAStartup", "Вызов не удался", 0 );        return 1;      }      m_listenSocket = socket( AF_INET, SOCK_STREAM, IPPROTO_TCP );      if( INVALID_SOCKET==m_listenSocket )      {        MessageBox( NULL, "Ошибка на socket", "Вызов не удался", 0 );        return 2;      }      SOCKADDR_IN sin;      sin.sin_family = AF_INET;      sin.sin_port = htons( m_defPORT );      sin.sin_addr.s_addr = INADDR_ANY;      if( SOCKET_ERROR==bind( m_listenSocket, (LPSOCKADDR)&sin, sizeof(sin) ) )       {         MessageBox( NULL, "Ошибка на bind", "Вызов не удался", 0 );        closesocket( m_listenSocket );        m_listenSocket = INVALID_SOCKET;        return 3;       }      if( SOCKET_ERROR==listen( m_listenSocket, SOMAXCONN) )      {        MessageBox( NULL, "Ошибка на listen", "Вызов не удался", 0 );        closesocket( m_listenSocket );        m_listenSocket = INVALID_SOCKET;        return 1;      }      WSAAsyncSelect( m_listenSocket, hWnd, WM_SOCKET, FD_ACCEPT|FD_CLOSE );    }    return 0;  case WM_SOCKET:    return SocketWndCall( hWnd, wParam, lParam );  }  return ::DefWindowProc( hWnd, msg, wParam, lParam );}LRESULT KModbusTcpServerImpl::SocketWndCall( HWND hWnd, SOCKET ss, LPARAM lParam ){  if( WSAGETSELECTERROR( lParam) )  {    tSocksDataCont_::iterator it = m_InDatas.find( ss );    char cbuf[256] = {};    if( m_InDatas.end()==it )      sprintf_s( cbuf, "Закрытие по ошибке??? %d\n", ss );    else      sprintf_s( cbuf, "Закрытие по ошибке %d, in=%d, out=%d\n", ss, it->second.allInBytes, it->second.allOutBites );    OutputDebugString( cbuf );    m_InDatas.erase( ss );    closesocket(ss);    return 0;  }  switch( WSAGETSELECTEVENT(lParam) )  {  default:    {      char cbuf[256] = {};      sprintf_s( cbuf, "Неизвестный FD 0x%04x\n", WSAGETSELECTEVENT(lParam) );      OutputDebugString( cbuf );    }    break;  case FD_ACCEPT:   // ----- requestПросходит запрос    {       sockaddr_in Cadd;       int Cadd_len=sizeof(Cadd);       SOCKET sNew = accept( ss, (sockaddr*)&Cadd, &Cadd_len );      if( INVALID_SOCKET==ss)        MessageBox( hWnd, "Не удался accept", "Вс¸ плохо", MB_OK);      m_InDatas.insert( tSocksDataCont_::value_type(sNew, tSocksDataCont_::mapped_type() ) ) ;      WSAAsyncSelect( sNew, hWnd, WM_SOCKET, FD_READ|FD_CLOSE );      {        char cbuf[256] = {};        sprintf_s( cbuf, "Новое подключение %d\n", sNew );        OutputDebugString( cbuf );      }    }break;   case FD_READ:    OnRead( ss );    break;   case FD_CLOSE:    {       tSocksDataCont_::iterator it = m_InDatas.find( ss );      char cbuf[256] = {};      if( m_InDatas.end()==it )        sprintf_s( cbuf, "Правильное закрытие??? %d\n", ss );      else        sprintf_s( cbuf, "Правильное закрытие %d, in=%d, out=%d\n", ss, it->second.allInBytes, it->second.allOutBites );      OutputDebugString( cbuf );      closesocket(ss);      m_InDatas.erase( ss );    }     break;   }  return 0L;}